import{_ as e,o as a,c as o,ah as i}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Full demo and activity log","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/demo-et-journal.md","filePath":"src/en/guide/admin/demo-et-journal.md"}'),n={name:"en/guide/admin/demo-et-journal.md"};function r(d,t,l,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="full-demo-and-activity-log" tabindex="-1">Full demo and activity log <a class="header-anchor" href="#full-demo-and-activity-log" aria-label="Permalink to &quot;Full demo and activity log&quot;">​</a></h1><p>This page groups two administrator features that have nothing to do with each other: activating a full, free demo of ERA, and reviewing the history of actions taken in the application.</p><h2 id="activate-the-full-demo" tabindex="-1">Activate the full demo <a class="header-anchor" href="#activate-the-full-demo" aria-label="Permalink to &quot;Activate the full demo&quot;">​</a></h2><p><strong>This feature only appears if your school is an Era Admission tenant still on the free tier</strong> — that is, a school using ERA only to manage its admissions application queue, without having purchased a license for the rest of the application yet. If your school already has an active license (or is already in a demo period), you won&#39;t see this button.</p><p>When available, the offer appears on the <strong>Dashboard</strong>:</p><ol><li>Click <strong>Activate the demo</strong>.</li><li>A dialog summarizes how many days every ERA pôle will be unlocked with no commitment.</li><li>Click <strong>Activate demo</strong> to confirm.</li></ol><p>Once activated, a banner on the dashboard shows how many days are left, then warns you as the end approaches. After that period, access switches to read-only until you purchase a license.</p><h2 id="review-the-activity-log" tabindex="-1">Review the activity log <a class="header-anchor" href="#review-the-activity-log" aria-label="Permalink to &quot;Review the activity log&quot;">​</a></h2><p><strong>Activity Log</strong> (in the menu&#39;s <strong>Administration</strong> group) is a history of who created, updated, or deleted what in the application, and when.</p><p>You can filter the list by:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Detail</th></tr></thead><tbody><tr><td>Actor</td><td>search by the name or email of the person behind the action</td></tr><tr><td>Entity</td><td>the type of record involved (student, class, payment...)</td></tr><tr><td>Action</td><td>Created, Updated, or Deleted</td></tr><tr><td>Date</td><td>a &quot;from&quot; / &quot;to&quot; range</td></tr></tbody></table><p>Click <strong>View details</strong> on a row to show, in a dialog, the technical detail of the fields changed by that action.</p><p>One important limitation to know: changes to many-to-many relationships (for example attaching a guardian to a student, or assigning a role to a user) are <strong>not</strong> captured in this log — only the direct creation, update, or deletion of a record appears here.</p>',13)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
